def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Find the repeated row that encodes the ordered list of colors.
    strip_rows = None
    palette = None
    for r in range(h - 2):
        if g[r] == g[r + 1] == g[r + 2]:
            colors = [c for c in g[r] if c != 0]
            if len(colors) >= 2:
                strip_rows = (r, r + 1, r + 2)
                palette = colors
                break

    if palette is None:
        return g

    # Find the existing shape in a color from the palette, excluding the strip.
    strip_cells = {(r, c) for r in strip_rows for c in range(w) if g[r][c]}
    template_color = None
    points = []
    for color in palette:
        pts = [(r, c) for r in range(h) for c in range(w)
               if g[r][c] == color and (r, c) not in strip_cells]
        if pts:
            template_color, points = color, pts
            break
    if template_color is None:
        return g

    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)
    shape = {(r - r0, c - c0) for r, c in points}
    shape_h = r1 - r0 + 1
    index = palette.index(template_color)

    # Remove the color key and draw one vertically stacked copy per color.
    for r, c in strip_cells:
        g[r][c] = 0
    for i, color in enumerate(palette):
        top = r0 + (i - index) * shape_h
        for dr, dc in shape:
            rr, cc = top + dr, c0 + dc
            if 0 <= rr < h and 0 <= cc < w:
                g[rr][cc] = color
    return g
